local memo={}
local function applySource(tableName,key,index,values)
 local rows=catalog[tableName] and catalog[tableName][key]; local old=rows and rows[index]
 if not old then return end
 local cache=memo[old]; if not cache then cache={}; memo[old]=cache end
 local row=cache[values]
 if not row then
  row={}; for k,v in pairs(old) do row[k]=v end
  for k,v in pairs(values) do if k~="sourceLocationHistory" then row[k]=v end end
  if values.sourceLocationHistory then
   local history={}; for _,v in ipairs(old.sourceLocationHistory or {}) do history[#history+1]=v end
   for _,v in ipairs(values.sourceLocationHistory) do history[#history+1]=v end
   row.sourceLocationHistory=history
  end
  cache[values]=row
 end
 rows[index]=row
end
