 local catalog=ns.ForeverCatalog
 local reviewed={[765]={kind="herb",nodeID=402,objectID=1617,name="Silverleaf",mapID=1413,zone="The Barrens",x=54.21,y=52.42,provenance="QuestieDB Forever",sourceRevision="v1.1.2:e1652ce62113c152da682baf2d6fb85f1396bcfb",sourceURL="https://github.com/Questie/QuestieDB/releases/tag/v1.1.2",coordinateEvidence="QuestieDB Forever object possible spawn",coordinateRole="possible-object-spawn",possibleSpawn=true,observedByPlayer=false,sourceEvidence={{source="QuestieDB Forever",revision="v1.1.2:e1652ce62113c152da682baf2d6fb85f1396bcfb",kind="item",recordKey="765",field="3",objectID=1617,sourceURL="https://github.com/Questie/QuestieDB/releases/tag/v1.1.2"},{source="QuestieDB Forever",revision="v1.1.2:e1652ce62113c152da682baf2d6fb85f1396bcfb",kind="object",recordKey="1617",field="4",areaID=17,sourceURL="https://github.com/Questie/QuestieDB/releases/tag/v1.1.2"}}},[2770]={kind="mine",nodeID=201,objectID=1731,name="Copper Vein",mapID=1413,zone="The Barrens",x=39.61,y=11.93,provenance="QuestieDB Forever",sourceRevision="v1.1.2:e1652ce62113c152da682baf2d6fb85f1396bcfb",sourceURL="https://github.com/Questie/QuestieDB/releases/tag/v1.1.2",coordinateEvidence="QuestieDB Forever object possible spawn",coordinateRole="possible-object-spawn",possibleSpawn=true,observedByPlayer=false,sourceEvidence={{source="QuestieDB Forever",revision="v1.1.2:e1652ce62113c152da682baf2d6fb85f1396bcfb",kind="item",recordKey="2770",field="3",objectID=1731,sourceURL="https://github.com/Questie/QuestieDB/releases/tag/v1.1.2"},{source="QuestieDB Forever",revision="v1.1.2:e1652ce62113c152da682baf2d6fb85f1396bcfb",kind="object",recordKey="1731",field="4",areaID=17,sourceURL="https://github.com/Questie/QuestieDB/releases/tag/v1.1.2"}}}}
 for itemID,source in pairs(reviewed) do
  local entry=catalog and catalog.reagents and catalog.reagents[itemID]
  if entry then
   entry.sources=entry.sources or {}
   local present=false
   for _,old in ipairs(entry.sources) do
    if old.kind==source.kind and old.objectID==source.objectID and old.mapID==source.mapID
      and old.x==source.x and old.y==source.y then present=true;break end
   end
   if not present then entry.sources[#entry.sources+1]=source end
  end
 end
end


