 records[#records+1]={["areaIDs"]={2437},["areaNameEvidence"]={["kind"]="db2_snapshot_AreaTable",["record_key"]="2437",["revision"]="1.60.1.70938",["source"]="Wago client DB2",["source_url"]="https://wago.tools/db2/AreaTable/csv?build=1.60.1.70938"},["coordinateStatus"]="No coordinates exported. ClientinstanceID is not GF UI-map waypointID.",["gameMapID"]=389,["identityEvidence"]={["kind"]="db2_snapshot_ItemSparse",["record_key"]="251342",["revision"]="1.60.1.70938",["source"]="Wago client DB2",["source_url"]="https://wago.tools/db2/ItemSparse/csv?build=1.60.1.70938"},["itemID"]=251342,["name"]="Taragaman the Hungerer",["npcAreaEvidence"]={["kind"]="npc",["record_key"]="11520",["revision"]="v1.1.2:e1652ce62113c152da682baf2d6fb85f1396bcfb",["source"]="QuestieDB Forever",["source_url"]="https://github.com/Questie/QuestieDB/releases/tag/v1.1.2"},["npcID"]=11520,["registeredDungeonCorroboration"]="Ragefire Chasm",["relationshipEvidence"]={["kind"]="item",["record_key"]="251342",["revision"]="v1.1.2:e1652ce62113c152da682baf2d6fb85f1396bcfb",["source"]="QuestieDB Forever",["source_url"]="https://github.com/Questie/QuestieDB/releases/tag/v1.1.2"},["uiMapID"]=nil,["zone"]="Ragefire Chasm"}
 for _,entry in ipairs(records) do
  local npcID,itemID,zone=entry.npcID,entry.itemID,entry.zone
  local label=catalog.npcLocationLabels[npcID]
  if not label then
   label={locations={},areaIDs={},evidence={}}
   catalog.npcLocationLabels[npcID]=label
  end
  label.locations=label.locations or {};local present=false
  for _,name in ipairs(label.locations) do if name==zone then present=true end end
  if not present then label.locations[#label.locations+1]=zone end
  label.areaIDs=label.areaIDs or {}
  for _,area in ipairs(entry.areaIDs or {}) do
   local exists=false;for _,old in ipairs(label.areaIDs) do if old==area then exists=true end end
   if not exists then label.areaIDs[#label.areaIDs+1]=area end
  end
  label.reviewedDungeonEvidence={npcArea=entry.npcAreaEvidence,areaName=entry.areaNameEvidence}
  catalog.byItem[itemID]=catalog.byItem[itemID] or {};local found=false
  for index,row in ipairs(catalog.byItem[itemID]) do
   if row.npcID==npcID and (row.kind=="Drop" or row.kind=="drop" or row.source=="Drop") then
    -- Original sources are pooled across items. Attach recipe-specific evidence
    -- to a shallow copy so one sibling cannot overwrite another's provenance.
    local copy={};for key,value in pairs(row) do copy[key]=value end
    copy.zone=copy.zone or zone;copy.dungeon=copy.dungeon or zone
    copy.recipeDungeonEvidence=entry;catalog.byItem[itemID][index]=copy;found=true
   end
  end
  if not found and entry.newPositiveRelationship then
   catalog.byItem[itemID][#catalog.byItem[itemID]+1]={kind="Drop",npcID=npcID,name=entry.name,
    zone=zone,dungeon=zone,provenance="Owner-provided exact recipe drop reference",
    recipeDungeonEvidence=entry}
  end
 end
end
