 local catalog=ns.ForeverCatalog
 for itemID,definition in pairs(additions)do
  local item=catalog.reagents[itemID]
  if not item then
   item={name=definition.name,professions=definition.browseCategories,sources={},ordinaryDrop=true}
   catalog.reagents[itemID]=item
  end
  item.sources=item.sources or{}
  local function key(row)return table.concat({row.kind or"",row.npcID or"",row.mapID or"",row.x or"",row.y or""},":")end
  local seen={};for _,row in ipairs(item.sources)do seen[key(row)]=true end
  for _,npc in ipairs(definition.npcs)do
   for _,point in ipairs(npc.points)do
    local row={};for name,value in pairs(npc.meta)do row[name]=value end
    row.areaID,row.mapID,row.zone,row.x,row.y=point[1],point[2],point[3],point[4],point[5]
    if not seen[key(row)]then item.sources[#item.sources+1]=row;seen[key(row)]=true end
   end
  end
 end
end
