 local catalog=ns.ForeverCatalog
 for itemID,addition in pairs(additions)do
  local item=catalog.reagents[itemID]
  if not item then
   item={name=addition.name,professions={},sources={}}
   catalog.reagents[itemID]=item
  end
  if not item.name or item.name=="" then item.name=addition.name end
  item.professions=item.professions or {}
  local hasFishing=false
  for _,name in ipairs(item.professions)do if name=="Fishing" then hasFishing=true;break end end
  if not hasFishing then item.professions[#item.professions+1]="Fishing" end
  item.sources=item.sources or {}
  local function identity(row)
   local evidence=row.sourceEvidence or {}
   return table.concat({row.kind or "",row.npcID or "",row.nodeID or "",row.mapID or "",
    row.x or "",row.y or "",row.areaID or "",row.referenceOnly and "reference" or "",
    row.sourceRevision or "",evidence.archiveGitBlobSHA1 or ""},":")
